class InputSelect extends HTMLElement {
  private selectedOption: HTMLButtonElement | null = null;
  private options: HTMLButtonElement[] = [];
  private isOpen = false;
  private optionsContainer: HTMLElement | null = null;
  private valueElement: HTMLElement | null = null;

  constructor() {
    super();
    this.handleClick = this.handleClick.bind(this);
    this.handleKeyDown = this.handleKeyDown.bind(this);
    this.handleBlur = this.handleBlur.bind(this);

    this.valueElement = this.querySelector('[js-input-select="value"]');
    this.optionsContainer = this.querySelector('[js-input-select="options"]');
    this.options = Array.from(
      this.querySelectorAll('[js-input-select="option"]'),
    );
  }

  connectedCallback() {
    // Set initial selection state
    let selectedOption = this.options.find(
      (opt) => opt.getAttribute("aria-selected") === "true",
    );

    // If no selected option, try to find default
    if (!selectedOption) {
      selectedOption = this.options.find((opt) =>
        opt.hasAttribute("data-default"),
      );
    }

    if (selectedOption) {
      this.selectOption(selectedOption, false);
    }

    this.setAttribute("tabindex", "0");
    this.addEventListener("click", this.handleClick);
    this.addEventListener("keydown", this.handleKeyDown);
    this.addEventListener("blur", this.handleBlur);
  }

  private handleClick(event: Event) {
    const target = event.target as HTMLElement;
    const option = target.closest(
      '[js-input-select="option"]',
    ) as HTMLButtonElement;

    if (option) {
      this.selectOption(option);
      this.closeDropdown();
    } else if (target === this || target.closest("uwp-input-select")) {
      this.toggleDropdown();
    }
  }

  private handleKeyDown(event: KeyboardEvent) {
    switch (event.key) {
      case "Enter":
      case " ":
        event.preventDefault();
        if (!this.isOpen) {
          this.openDropdown();
        } else if (this.selectedOption) {
          this.selectOption(this.selectedOption);
          this.closeDropdown();
        }
        break;
      case "Escape":
        if (this.isOpen) {
          this.closeDropdown();
        }
        break;
      case "ArrowDown":
        event.preventDefault();
        this.navigateOptions(1);
        break;
      case "ArrowUp":
        event.preventDefault();
        this.navigateOptions(-1);
        break;
      case "Home":
        event.preventDefault();
        if (this.isOpen) {
          this.navigateToEdge(0);
        }
        break;
      case "End":
        event.preventDefault();
        if (this.isOpen) {
          this.navigateToEdge(this.options.length - 1);
        }
        break;
    }
  }

  private handleBlur(event: FocusEvent) {
    // Close dropdown when focus moves outside the component
    if (!this.contains(event.relatedTarget as Node)) {
      this.closeDropdown();
    }
  }

  private toggleDropdown() {
    if (this.isOpen) {
      this.closeDropdown();
    } else {
      this.openDropdown();
    }
  }

  private openDropdown() {
    if (!this.optionsContainer || this.classList.contains("is-disabled")) {
      return;
    }

    this.isOpen = true;
    this.setAttribute("aria-expanded", "true");

    // Set display first, then trigger animation
    this.optionsContainer.style.display = "flex";
    this.optionsContainer.style.flexDirection = "column";

    // Force reflow to ensure display change is applied before animation
    void this.optionsContainer.offsetHeight;

    this.optionsContainer.classList.add("is-open");

    // If there's a selected option, highlight it
    const selectedOption = this.options.find(
      (opt) => opt.getAttribute("aria-selected") === "true",
    );
    if (selectedOption) {
      this.highlightOption(selectedOption);
    } else if (this.options.length) {
      this.highlightOption(this.options[0]);
    }
  }

  private closeDropdown() {
    if (!this.optionsContainer) return;

    this.isOpen = false;
    this.setAttribute("aria-expanded", "false");
    this.optionsContainer.classList.remove("is-open");

    // Hide the dropdown after animation completes
    setTimeout(() => {
      if (!this.isOpen && this.optionsContainer) {
        this.optionsContainer.style.display = "none";
      }
    }, 200); // Match CSS transition duration

    this.selectedOption = null;
  }

  private selectOption(option: HTMLButtonElement, dispatchEvent = true) {
    if (!this.valueElement) return;

    // Update selected state
    this.options.forEach((opt) => {
      opt.setAttribute("aria-selected", "false");
    });
    option.setAttribute("aria-selected", "true");

    // Update the visible selection
    this.valueElement.textContent = option.textContent;

    // Dispatch change event
    if (dispatchEvent) {
      const event = new CustomEvent("change", {
        detail: {
          value: option.getAttribute("data-value")?.trim(),
          label: option.textContent?.trim(),
          name: this.getAttribute("name")?.trim(),
        },
      });

      this.dispatchEvent(event);
    }
  }

  private navigateOptions(direction: number) {
    if (!this.isOpen) {
      this.openDropdown();
      return;
    }

    const currentIndex = this.selectedOption
      ? this.options.indexOf(this.selectedOption)
      : -1;
    let newIndex = currentIndex + direction;

    if (newIndex < 0) newIndex = this.options.length - 1;
    if (newIndex >= this.options.length) newIndex = 0;

    this.highlightOption(this.options[newIndex]);
  }

  private navigateToEdge(index: number) {
    if (this.options[index]) {
      this.highlightOption(this.options[index]);
    }
  }

  private highlightOption(option: HTMLButtonElement) {
    this.selectedOption = option;
    option.focus();
  }
}

customElements.define("uwp-input-select", InputSelect);
